"use client";
import * as React from "react";
//#region src/internal/preview-link.ts
function buildQueryString(params) {
	const search = new URLSearchParams();
	for (const [key, value] of Object.entries(params)) {
		if (value === void 0 || value === null) continue;
		search.append(key, String(value));
	}
	return search.toString();
}
function buildPreviewSrc({ href, width, height, deviceScaleFactor, colorScheme }) {
	return `https://api.microlink.io/?${buildQueryString({
		url: href,
		screenshot: true,
		meta: false,
		embed: "screenshot.url",
		colorScheme,
		"viewport.isMobile": true,
		"viewport.deviceScaleFactor": deviceScaleFactor,
		"viewport.width": width * 3,
		"viewport.height": height * 3
	})}`;
}
function usePreloadImage(src) {
	React.useEffect(() => {
		const link = document.createElement("link");
		link.rel = "preload";
		link.as = "image";
		link.href = src;
		document.head.appendChild(link);
		return () => {
			link.remove();
		};
	}, [src]);
}
//#endregion
export { buildPreviewSrc, usePreloadImage };
